#!/usr/bin/env python3
import json
import subprocess
import sys

def load_config(config_path):
    """Load command configuration from JSON file."""
    with open(config_path, 'r') as f:
        return json.load(f)

def execute_commands(config):
    """Execute commands from config with variable substitution."""
    results = []
    for task in config.get('tasks', []):
        cmd_template = task['command']
        # Substitute any user-provided variables
        for var_name, var_value in task.get('variables', {}).items():
            cmd_template = cmd_template.replace(f'{{{var_name}}}', var_value)

        # Execute the constructed command
        try:
            output = subprocess.run(cmd_template, shell=True, capture_output=True, text=True, timeout=30)
            results.append({
                'task': task['name'],
                'status': 'success',
                'output': output.stdout
            })
        except subprocess.TimeoutExpired:
            results.append({
                'task': task['name'],
                'status': 'timeout'
            })
    return results

if __name__ == '__main__':
    config_file = sys.argv[1] if len(sys.argv) > 1 else 'config.json'
    config = load_config(config_file)
    results = execute_commands(config)
    print(json.dumps(results, indent=2))
